<p><a href="<?= $link('/templates') ?>">← All templates</a></p><div class="two-columns"><section class="card"><h2><?= $e($template['name']) ?></h2><p class="muted"><?= $e($template['description']) ?></p><div class="table-scroll"><table><thead><tr><th>Field</th><th>Type</th><th>Required</th><th></th></tr></thead><tbody><?php foreach($template['fields'] as $f): ?><tr><td><?= $e($f['name']) ?></td><td><?= $e($f['field_type']) ?></td><td><?= $f['required']?'Yes':'No' ?></td><td><?php if($f['archived']): ?><span class="badge">Archived</span><?php else: ?><form method="post" action="<?= $link('/template-fields/'.$f['id'].'/archive') ?>" data-confirm="Archive this field? Existing values will be preserved."><?= $csrf ?><button class="text-link">Archive</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><p class="help">Archiving removes a field from edit forms and preserves its existing values.</p></section><section class="card"><h2>Add custom field</h2><form method="post" action="<?= $link('/templates/'.$template['id'].'/fields') ?>"><?= $csrf ?><label>Field name<input name="name" required></label><label>Type<select name="type"><?php foreach(['text','multiline','number','date','boolean','url','choice'] as $t): ?><option value="<?= $e($t) ?>"><?= $e(ucfirst($t)) ?></option><?php endforeach; ?></select></label><label>Choice options (comma separated)<input name="options"></label><label class="checkbox"><input type="checkbox" name="required" value="1">Required</label><button class="button">Add field</button></form></section></div>
